@interface Circle : NSObject

@property (nonatomic, assign) double x;
@property (nonatomic, assign) double y;
@property (nonatomic, assign) double r;

- (instancetype)initWithX:(double)x y:(double)y r:(double)r;

- (double)x;
- (double)y;
- (double)r;

- (int)getTopologyWithOther:(Circle *)other;

@end

@implementation Circle

- (instancetype)initWithX:(double)x y:(double)y r:(double)r {
    self = [super init];
    if (self) {
        _x = x;
        _y = y;
        _r = r;
    }
    return self;
}

- (double)x {
    return _x;
}

- (double)y {
    return _y;
}

- (double)r {
    return _r;
}

- (int)getTopologyWithOther:(Circle *)other {
    int retval = 0;

    double distance;
    distance = sqrt(pow(_x - other.x, 2) + pow(_y - other.y, 2));

    if (distance + other.r < _r)
        return 2;
    if (distance + _r < other.r)
        return -2;
    if (distance <= _r + other.r)
        return 1;
    if (distance > _r + other.r)
        return 0;

    return retval;
}

@end

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        NSInputStream *inputStream = [NSInputStream inputStreamWithFileAtPath:@"/dev/stdin"];
        [inputStream open];

        NSMutableData *data = [NSMutableData data];
        char buffer[1024];
        NSUInteger bytesRead;
        while ((bytesRead = [inputStream read:buffer maxLength:1024]) > 0) {
            [data appendBytes:buffer length:bytesRead];
        }

        NSString *inputString = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
