                Circle *circle1 = [[Circle alloc] initWithX:dp[0] y:dp[1] r:dp[2]];
                Circle *circle2 = [[Circle alloc] initWithX:dp[3] y:dp[4] r:dp[5]];

                int topology = [circle1 getTopologyWithOther:circle2];
                NSLog(@"%d", topology);

                free(dp);
            }
        }

        [inputStream close];
    }
    return 0;
}

