#import <Foundation/Foundation.h>

double getSlope(NSPoint a, NSPoint b) {
    if (a.y == b.y) {
        return DBL_MAX;
    }
    return -(b.x - a.x) / (b.y - a.y);
}

NSPoint makeSolution (NSPoint p1, double e1, NSPoint p2, double e2) {
    double a, b, c, d;
    double x = 0.0, y = 0.0;

    a = e1;
    if (!isinf(a)) {
        b = p1.y - a * p1.x;
    } else {
        b = NAN;
    }
    c = e2;
    if (!isinf(c)) {
        d = p2.y - c * p2.x;
    } else {
        d = NAN;
    }

    if (!isnan(b) && !isnan(d)) {
        x = (d - b) / (a - c);
        y = (a * d - b * c) / (a - c);
    } else if (isnan(b)) {
        x = p1.x;
        y = c * x + d;
    } else if (isnan(d)) {
        x = p2.x;
        y = a * x + b;
    }

    return NSMakePoint(x, y);
}

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        int n;
        NSPoint a, b, c;
        NSPoint middle1, middle2;
        double slope1, slope2;
        NSPoint solve;
        double r;

        scanf("%d", &n);
        for (int i = 0; i < n; i++) {
            scanf("%lf %lf %lf %lf %lf %lf", &a.x, &a.y, &b.x, &b.y, &c.x, &c.y);

            middle1 = NSMakePoint((a.x + b.x) / 2.0, (a.y + b.y) / 2.0);
            middle2 = NSMakePoint((b.x + c.x) / 2.0, (b.y + c.y) / 2.0);
            slope1 = getSlope(a, b);
            slope2 = getSlope(b, c);
            solve = makeSolution(middle1, slope1, middle2, slope2);
            r = sqrt((solve.x - a.x) * (solve.x - a.x) + (solve.y - a.y) * (solve.y - a.y));
            printf("%.3f %.3f %.3f\n", solve.x, solve.y, r);
        }
    }
    return 0;
}

