#import <stdio.h>
#import <stdlib.h>
#import <string.h>
#import <math.h>

typedef struct {
    double x, y;
} P;

double EPS = 1e-10;

double accurateTotal(double a, double b) {
    if (fabs(a + b) < EPS * (fabs(a) + fabs(b))) {
        return 0.0;
    }
    return a + b;
}

P add(P a, P b) {
    return (P) {accurateTotal(a.x, b.x), accurateTotal(a.y, b.y)};
}

P sub(P a, P b) {
    return (P) {accurateTotal(a.x, -b.x), accurateTotal(a.y, -b.y)};
}

P mul(P a, double k) {
    return (P) {a.x * k, a.y * k};
}

double dot(P a, P b) {
    return accurateTotal(a.x * b.x, a.y * b.y);
}

double det(P a, P b) {
    return accurateTotal(a.x * b.y, -a.y * b.x);
}

void solve() {
    int n;
    scanf("%d", &n);
    while (n--) {
        P ps[4];
