#import <Foundation/Foundation.h>

BOOL *sieve(int n) {
    BOOL *isPrime = malloc(sizeof(BOOL) * (n + 1));
    for (int i = 0; i <= n; i++) {
        isPrime[i] = YES;
    }
    for (int i = 4; i <= n; i += 2) {
        isPrime[i] = NO;
    }
    for (int i = 3; i * i <= n; i += 2) {
        for (int j = 3; i * j <= n; j += 2) {
            isPrime[i * j] = NO;
        }
    }
    return isPrime;
}

int solve(int n) {
    int ret = 0;
    BOOL *primes = sieve(n);
    for (int i = 2; i <= n / 2; i++) {
        if (!primes[i]) continue;
        ret = primes[n - i] ? ret + 1 : ret;
    }
    free(primes);
    return ret;
}

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        while (true) {
            int n;
            scanf("%d", &n);
            if (n == 0) break;
            printf("%d\n", solve(n));
        }
    }
    return 0;
}
